<script>

(function () {
    var token=document.querySelector('meta[name="csrf-token"]')?.content;
    document.querySelectorAll('[data-reference-picker]').forEach(function (picker) {
        var search=picker.querySelector('[data-reference-search]'), id=picker.querySelector('[data-reference-id]'), results=picker.querySelector('[data-reference-results]'), create=picker.querySelector('[data-reference-create]'), panel=picker.querySelector('[data-reference-create-form]'), loading=picker.querySelector('[data-reference-loading]'), timer, activeIndex=-1;
        function closeResults(){results.classList.add('d-none');search.setAttribute('aria-expanded','false');activeIndex=-1}
        function select(item) {
            id.value=item.id; search.value=item.name; closeResults(); create.classList.add('d-none'); panel.classList.add('d-none');
            ['contact_name','contact_phone','location_name','address','google_maps_url'].forEach(function(field){var target=document.querySelector('[name="'+field+'"]');if(target&&item[field])target.value=item[field]});
            search.classList.add('is-valid'); search.focus();
        }
        function render(items,term){
            results.innerHTML='';
            if(!items.length){var empty=document.createElement('div');empty.className='ramadan-picker-empty';empty.textContent='لا توجد نتائج مطابقة';results.appendChild(empty)}
            items.forEach(function(item,index){var button=document.createElement('button');button.type='button';button.className='list-group-item list-group-item-action';button.setAttribute('role','option');button.dataset.index=index;button.innerHTML='<strong></strong><small></small>';button.querySelector('strong').textContent=item.name;button.querySelector('small').textContent=[item.contact_phone,item.location_name].filter(Boolean).join(' · ');button.addEventListener('click',function(){select(item)});results.appendChild(button)});
            results.classList.remove('d-none');search.setAttribute('aria-expanded','true');create.classList.remove('d-none');create.querySelector('[data-reference-name]').textContent='"'+term+'"';picker.querySelector('[data-create-field="name"]').value=term;
        }
        search.addEventListener('input',function(){id.value='';search.classList.remove('is-valid');clearTimeout(timer);var term=search.value.trim();if(term.length<1){closeResults();create.classList.add('d-none');return}loading.classList.remove('d-none');timer=setTimeout(function(){fetch(picker.dataset.searchUrl+'?q='+encodeURIComponent(term),{headers:{Accept:'application/json'}}).then(function(response){if(!response.ok)throw new Error();return response.json()}).then(function(body){render(body.data||[],term)}).catch(function(){results.innerHTML='<div class="ramadan-picker-empty text-danger">تعذر تحميل النتائج. حاول مرة أخرى.</div>';results.classList.remove('d-none')}).finally(function(){loading.classList.add('d-none')})},250)});
        search.addEventListener('keydown',function(event){var options=Array.from(results.querySelectorAll('[role="option"]'));if(event.key==='Escape'){closeResults();return}if(!options.length)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();activeIndex=(activeIndex+(event.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach(function(option,i){option.classList.toggle('active',i===activeIndex)});options[activeIndex].scrollIntoView({block:'nearest'})}else if(event.key==='Enter'&&activeIndex>=0){event.preventDefault();options[activeIndex].click()}});
        picker.querySelector('[data-reference-clear]').addEventListener('click',function(){id.value='';search.value='';search.classList.remove('is-valid');closeResults();create.classList.add('d-none');search.focus()});
        create.addEventListener('click',function(){panel.classList.remove('d-none');closeResults();panel.querySelector('[data-create-field="name"]').focus()});
        picker.querySelector('[data-reference-more]').addEventListener('click',function(event){var optional=picker.querySelector('[data-reference-optional]'),expanded=optional.classList.contains('d-none');optional.classList.toggle('d-none',!expanded);event.currentTarget.setAttribute('aria-expanded',expanded?'true':'false')});
        picker.querySelector('[data-reference-cancel]').addEventListener('click',function(){panel.classList.add('d-none');picker.querySelector('[data-reference-error]').textContent=''});
        picker.querySelector('[data-reference-save]').addEventListener('click',function(){
            var payload={},errorBox=picker.querySelector('[data-reference-error]'),save=this;errorBox.textContent='';picker.querySelectorAll('[data-create-field]').forEach(function(input){payload[input.dataset.createField]=input.value;input.classList.remove('is-invalid')});save.disabled=true;
            fetch(picker.dataset.createUrl,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify(payload)}).then(async function(response){var body=await response.json().catch(function(){return {}});if(!response.ok||!body.success)throw body;return body.data}).then(function(item){select(item);panel.querySelectorAll('[data-create-field]').forEach(function(input){input.value=''});errorBox.classList.remove('text-danger');errorBox.classList.add('text-success');errorBox.textContent='تمت إضافة الجهة واختيارها بنجاح.'}).catch(function(error){var errors=error.errors||{},messages=Object.values(errors).flat();Object.keys(errors).forEach(function(field){picker.querySelector('[data-create-field="'+field+'"]')?.classList.add('is-invalid')});errorBox.classList.remove('text-success');errorBox.classList.add('text-danger');errorBox.textContent=messages[0]||error.message||'تعذر حفظ الجهة.';picker.querySelector('.is-invalid')?.focus()}).finally(function(){save.disabled=false});
        });
    });
    var locationType=document.querySelector('[name="location_type"]'),hostType=document.querySelector('[name="host_type"]');
    function updateConditionalFields(){
        var inside=locationType?.value==='inside_center',local=hostType?.value==='local_community';
        document.querySelector('[data-outside-location]')?.classList.toggle('d-none',inside);
        if(inside){var map=document.querySelector('[name="google_maps_url"]');if(map)map.value=''}
        document.querySelector('[data-organization-picker]')?.classList.toggle('d-none',local);
        document.querySelector('[data-community-picker]')?.classList.toggle('d-none',!local);
        document.querySelectorAll('[data-community-only]').forEach(function(element){element.classList.toggle('d-none',!local)});
        var irrelevant=document.querySelector(local?'[name="community_organization_id"]':'[name="local_community_id"]');if(irrelevant)irrelevant.value='';
    }
    locationType?.addEventListener('change',updateConditionalFields);hostType?.addEventListener('change',updateConditionalFields);updateConditionalFields();
})();

document.addEventListener('click', function (event) {
    if (event.target.matches('.remove-row')) event.target.closest('.planning-row').remove();
    if (event.target.matches('.add-row')) {
        var card=event.target.closest('[data-repeat]'), source=card.querySelector('.planning-row');
        if (!source) return;
        var clone=source.cloneNode(true), index=Date.now();
        clone.querySelectorAll('[name]').forEach(function (input) {
            input.name=input.name.replace(/\[\d+\]/,'['+index+']');
            if (input.type!=='hidden' && input.tagName!=='SELECT') input.value='';
            if (input.type==='hidden') input.value='';
        });
        card.querySelector('.card-body').appendChild(clone);
    }
});
</script>
